class Solution {
public:
    int findTheLongestBalancedSubstring(std::string s) {
        int zeros = 0, ones = 0;
        int max_len = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            if (s[i] == '0') {
                if (i > 0 && s[i - 1] == '1') {
                    zeros = 1;
                    ones = 0;
                } else {
                    zeros++;
                }
            } else {
                ones++;
                max_len = std::max(max_len, 2 * std::min(zeros, ones));
            }
        }
        return max_len;
    }
};

class Solution {
    public int findTheLongestBalancedSubstring(String s) {
        int zeros = 0, ones = 0;
        int maxLen = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '0') {
                if (i > 0 && s.charAt(i - 1) == '1') {
                    zeros = 1;
                    ones = 0;
                } else {
                    zeros++;
                }
            } else {
                ones++;
                maxLen = Math.max(maxLen, 2 * Math.min(zeros, ones));
            }
        }
        return maxLen;
    }
}

var findTheLongestBalancedSubstring = function(s) {
    let zeros = 0, ones = 0;
    let maxLen = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '0') {
            if (i > 0 && s[i - 1] === '1') {
                zeros = 1;
                ones = 0;
            } else {
                zeros++;
            }
        } else {
            ones++;
            maxLen = Math.max(maxLen, 2 * Math.min(zeros, ones));
        }
    }
    return maxLen;
};
